-- S-M04-01-CROSS-005（店舗横断検索在庫(005)）
-- 流す時点: 投入方法の「商品規格の登録時に、営業中の全店舗×在庫区分（EC-CUBE・スマレジ）の店舗別在庫が在庫0で自動作…」を終えたあと、次の「比較用の3件は在庫数の指定が無いため在庫0のままにする。」より前。手順書（S-M04-01-CROSS-005.md）の「DBへ直接設定する部分（SQL）」と同じ。
BEGIN;

-- [1] 文（投入方法）: CROSS-OSAKA-SR-005の大阪支店・スマレジ、CROSSCMP-TKY-EC-005の東京本店・EC-CUBE、CROSSCMP-TKY-SR-005の東京本店・スマレジ、CROSSCMP-OSK-EC-005の大阪支店・EC-CUBE以外の店舗別在庫は画面で削除できないためDBで直接削
--     備考: 残す組(店舗・在庫区分)以外の、その商品コードの店舗別在庫だけを消す(ほかの商品の在庫は消さない)。店舗は店舗名で引き、残す店舗・残す在庫がそれぞれ1件に決まることを確かめる
DO $$ DECLARE n bigint; BEGIN SELECT (SELECT count(*) FROM dtb_base_info WHERE shop_name = '大阪支店') INTO n; IF n IS DISTINCT FROM 1 THEN RAISE EXCEPTION '残す店舗「大阪支店」が1件に決まらない（%件）', n; END IF; END $$;
DO $$ DECLARE n bigint; BEGIN SELECT (SELECT count(*) FROM dtb_base_info WHERE shop_name = '東京本店') INTO n; IF n IS DISTINCT FROM 1 THEN RAISE EXCEPTION '残す店舗「東京本店」が1件に決まらない（%件）', n; END IF; END $$;
DO $$ DECLARE n bigint; BEGIN SELECT (SELECT count(*) FROM dtb_product_class WHERE product_code = 'CROSS-OSAKA-SR-005') INTO n; IF n IS DISTINCT FROM 1 THEN RAISE EXCEPTION '商品コードCROSS-OSAKA-SR-005が1件に決まらない（%件）', n; END IF; END $$;
DO $$ DECLARE n bigint; BEGIN SELECT (SELECT count(*) FROM dtb_product_stock WHERE product_class_id = (SELECT id FROM dtb_product_class WHERE product_code = 'CROSS-OSAKA-SR-005') AND base_info_id = (SELECT id FROM dtb_base_info WHERE shop_name = '大阪支店') AND stock_location_id = 2) INTO n; IF n IS DISTINCT FROM 1 THEN RAISE EXCEPTION '残す在庫（商品コードCROSS-OSAKA-SR-005・店舗大阪支店・在庫区分2）が1件に決まらない（%件）', n; END IF; END $$;
DELETE FROM dtb_inventory_plan_detail_edit_history WHERE inventory_plan_detail_id IN (SELECT id FROM dtb_inventory_plan_detail WHERE product_stock_id IN (SELECT id FROM dtb_product_stock WHERE product_class_id = (SELECT id FROM dtb_product_class WHERE product_code = 'CROSS-OSAKA-SR-005') AND NOT ((base_info_id = (SELECT id FROM dtb_base_info WHERE shop_name = '大阪支店') AND stock_location_id = 2))));
